style.css:
@-moz-document domain("shein.com") {
/* fundo */
body {
    background-color: #fff5f7 !important;
}

/* topo */
header {
    background-color: #ffeef2 !important;
}

/* cards */
.product-list-item {
    background-color: rgba(255, 255, 255, 0.85);
    border-radius: 12px;
}

/* hover */
.product-list-item:hover {
    background-color: rgba(255, 182, 193, 0.2);
}

/* textos */
span, p {
    color: #000 !important;
}
}
